import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ml import *
tee('m39'); reset()
n = Node('m39', cache=0.5); n.start(); c = n.client(); db = c.test
N = 1000000
fill(db.t, N, lambda i: {'_id': i, 'a': i % 100, 'b': i % 1000, 'pad': 'x' * 30}, batch=50000)
db.t.create_index('a')
print(f'== 一:{N:,} 个文档,a = i % 100 有索引(b 没有索引)。几种数数的写法耗时(各 5 次中位数)')
rows = [('estimatedDocumentCount()', lambda: db.t.estimated_document_count()), ('count_documents({})', lambda: db.t.count_documents({})), ('count_documents({a: 5})(a 有索引)', lambda: db.t.count_documents({'a': 5})), ('count_documents({b: 5})(b 无索引)', lambda: db.t.count_documents({'b': 5})), ('命令 count({})(旧)', lambda: db.command('count', 't')), ('命令 count({a: 5})(旧)', lambda: db.command('count', 't', query={'a': 5}))]
for nm_, f in rows: print(f'  {nm_:<34}{fm(bench(f, 5)):>10}   = {f() if not isinstance(f(), dict) else f()["n"]:,}')
print('== 二:它们各自执行的东西(explain)')
msh(n, 'var e = db.t.explain().count({a: 5}); ({stage: e.queryPlanner.winningPlan.stage, input: e.queryPlanner.winningPlan.inputStage && e.queryPlanner.winningPlan.inputStage.stage})', label='db.t.explain().count({a: 5})')
msh(n, 'var e = db.t.explain().count({}); ({stage: e.queryPlanner.winningPlan.stage, fast: e.queryPlanner.winningPlan.fastCount})', label='db.t.explain().count({})')
msh(n, EXJS + 'var e = db.t.explain("executionStats").aggregate([{$match: {a: 5}}, {$group: {_id: 1, n: {$sum: 1}}}]); ex(e)', label='countDocuments({a: 5}) 内部是 aggregate [{$match: {a: 5}}, {$group: {_id: 1, n: {$sum: 1}}}]', n=12)
msh(n, EXJS + 'var e = db.t.explain("executionStats").aggregate([{$match: {b: 5}}, {$group: {_id: 1, n: {$sum: 1}}}]); ex(e)', label='countDocuments({b: 5}) 内部的 aggregate', n=12)
msh(n, 'db.t.aggregate([{$collStats: {count: {}}}])', label='$collStats {count: {}}')
print('== 三:estimatedDocumentCount 读的是元数据计数,正常运行时准确;kill -9 后的计数在重启后呢?(新起一个 mongod,写入 30 万个文档后立即 SIGKILL)')
n2 = Node('m39u'); n2.start(); c2 = n2.client()
fill(c2.test.u, 300000, lambda i: {'_id': i, 'x': i}, batch=50000)
print(f'  SIGKILL 之前:estimatedDocumentCount = {c2.test.u.estimated_document_count():,},countDocuments = {c2.test.u.count_documents({}):,}')
n2.p.kill(); n2.p.wait(); n2.start(); c2 = n2.client()
print(f'  重启之后:estimatedDocumentCount = {c2.test.u.estimated_document_count():,},countDocuments = {c2.test.u.count_documents({}):,}')
vv = c2.test.command('validate', 'u'); print(f'  validate 之后:estimatedDocumentCount = {c2.test.u.estimated_document_count():,}(validate 返回 nrecords = {vv.get("nrecords"):,})')
n2.stop()
print('== 四:删除大量文档后:元数据计数立即更新')
db.t.delete_many({'a': {'$lt': 50}})
print(f'  delete_many({{a: {{$lt: 50}}}}) 之后:estimatedDocumentCount = {db.t.estimated_document_count():,},countDocuments = {db.t.count_documents({}):,}')
print('== 五:count 带 limit / skip,以及 distinct:代价取决于要数多少')
print(f'  count_documents({{}}, limit=1000):{fm(bench(lambda: db.t.count_documents({}, limit=1000), 5))};不带 limit:{fm(bench(lambda: db.t.count_documents({}), 5))}')
print(f'  count_documents({{a: 60}}, limit=1000):{fm(bench(lambda: db.t.count_documents({"a": 60}, limit=1000), 5))};不带 limit:{fm(bench(lambda: db.t.count_documents({"a": 60}), 5))}')
msh(n, 'db.t.distinct("a").length', label='db.t.distinct("a").length    // a 有索引')
print(f'  distinct("a") 耗时 {fm(bench(lambda: db.t.distinct("a"), 5))};distinct("b")(无索引)耗时 {fm(bench(lambda: db.t.distinct("b"), 3))}')
print('== 六:什么时候用哪个:总文档数用 estimatedDocumentCount;带过滤条件的精确值用 countDocuments;命令 count / 驱动旧方法 count() 已不推荐,在 mongosh 里 db.t.count() 的行为')
msh(n, 'db.t.count()', label='db.t.count()    // mongosh 旧方法')
msh(n, 'db.t.count({a: 60})', label='db.t.count({a: 60})')
n.stop()
